"""Generate uptake, concentration-derivative and sensitivity plots from C++ data."""

from __future__ import annotations

#==============================================================================
# Python standard library imports
#==============================================================================

import argparse
import csv
import io
import subprocess
from pathlib import Path

#==============================================================================
# Third-party library imports
#==============================================================================

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

# Keep generated SVG identifiers deterministic across repeated builds.
matplotlib.rcParams["svg.hashsalt"] = "isothermpp-scientific-figures"


def load_example():
    """Read numerically evaluated reference data from the compiled C++ example."""
    parser = argparse.ArgumentParser()
    parser.add_argument("executable", type=Path)
    parser.add_argument("--output", type=Path, default=Path("output"))
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=True)
    output = subprocess.run([str(args.executable.resolve())], check=True,
                            text=True, capture_output=True).stdout
    records = list(csv.DictReader(io.StringIO(output)))
    if not records:
        raise ValueError("The C++ example returned no CSV records")
    return args.output, output, records


def figure(output: Path, filename: str, xs, ys, xlabel: str, ylabel: str, title: str):
    """Create the approved vector plot with an explicit axis definition."""
    fig, axis = plt.subplots(figsize=(7.6, 4.3), layout="constrained")
    axis.plot(xs, ys, color="#087F82", linewidth=2.8)
    axis.scatter(xs[::14], ys[::14], color="#DF735F", s=17, zorder=3)
    axis.set(title=title, xlabel=xlabel, ylabel=ylabel)
    axis.grid(True, alpha=0.20)
    axis.spines[["right", "top"]].set_visible(False)
    fig.savefig(output / f"{filename}.svg", transparent=True, metadata={"Date": None})
    plt.close(fig)


def main():
    output, raw_csv, records = load_example()
    (output / "henry_data.csv").write_text(raw_csv, encoding="utf-8")
    x = [float(r["concentration"]) for r in records]
    q = [float(r["uptake"]) for r in records]
    figure(output, "henry_curve", x, q, "Equilibrium concentration, $C_e$",
           "Adsorbed amount, $q_e$", "Henry isotherm plot")
    derivative = [float(r["derivative"]) for r in records]
    figure(output, "henry_derivative", x, derivative,
           "Equilibrium concentration, $C_e$",
           r"Concentration derivative, $\mathrm{d}q_e/\mathrm{d}C_e$",
           "Henry — concentration derivative")
    sensitivity = [float(r["sensitivity_kh"]) for r in records]
    figure(output, "henry_sensitivity", x, sensitivity,
           "Equilibrium concentration, $C_e$",
           r"Scaled sensitivity, $K_H\,\partial q_e/\partial K_H$",
           "Henry — numerical parameter sensitivity")


if __name__ == "__main__":
    main()
